import { readFile } from "node:fs/promises";
import path from "node:path";
import { cacheLife } from "next/cache";
import index from "@/data/polling-units/index.json";
import { getLga, getState, getStateData } from "@/lib/candidates";

/**
 * INEC's polling unit list (176,846 units), via github.com/saidiadegoke/nigeria-inec-geo.
 * Generated by scripts/polling-units/build.py. Names and locations are verbatim from INEC.
 */

/** [unit code, name, location (empty when it repeats the name)] */
export type UnitRow = [string, string, string];
export type Ward = { c: string; n: string; u: UnitRow[] };
export type LgaUnits = { code: string; wards: Ward[] };

export const PU_SOURCE = "https://cvr.inecnigeria.org/pu";
export const PU_AS_OF = new Date(index.scrapedAt).toLocaleDateString("en-GB", {
  day: "numeric",
  month: "long",
  year: "numeric",
  timeZone: "Africa/Lagos",
});
export const PU_COUNTS = index.counts;

const LGA_BY_CODE = index.lgas as Record<string, string>;
const STATE_CODE = index.states as Record<string, string>;

/** "24/02/05/012" (or with dashes/spaces) → ["24","02","05","012"], or null if malformed. */
export function parseUnitCode(raw: string): [string, string, string, string] | null {
  const parts = raw.trim().split(/[\s/\-.]+/).filter(Boolean);
  if (parts.length !== 4 || !parts.every((p) => /^\d{1,3}$/.test(p))) return null;
  const [s, l, w, u] = parts;
  return [s.padStart(2, "0"), l.padStart(2, "0"), w.padStart(2, "0"), u.padStart(3, "0")];
}

export const unitSlug = (code: string) => code.replaceAll("/", "-");
export const unitHref = (code: string) => `/get-ready/polling-unit/unit/${unitSlug(code)}`;
export const areaHref = (state: string, lga: string) => `/get-ready/polling-unit/${state}/${lga}`;

export function lgaCode(stateSlug: string, lgaSlug: string) {
  const code = STATE_CODE[stateSlug];
  if (!code) return null;
  return Object.keys(LGA_BY_CODE).find((k) => LGA_BY_CODE[k] === `${stateSlug}/${lgaSlug}`) ?? null;
}

export async function getLgaUnits(stateSlug: string, lgaSlug: string): Promise<LgaUnits | null> {
  "use cache";
  cacheLife("max");
  if (!getLga(stateSlug, lgaSlug)) return null;
  const file = path.join(process.cwd(), "src/data/polling-units", stateSlug, `${lgaSlug}.json`);
  return JSON.parse(await readFile(file, "utf8")) as LgaUnits;
}

/** A unit with its ward, LGA and state, or null when INEC's list has no such code. */
export async function getUnit(raw: string) {
  const parts = parseUnitCode(raw);
  if (!parts) return null;
  const [s, l, w, u] = parts;
  const where = LGA_BY_CODE[`${s}/${l}`];
  if (!where) return null;
  const [stateSlug, lgaSlug] = where.split("/");
  const data = await getLgaUnits(stateSlug, lgaSlug);
  const ward = data?.wards.find((x) => x.c === w);
  const row = ward?.u.find((x) => x[0] === u);
  if (!ward || !row) return null;
  return {
    code: `${s}/${l}/${w}/${u}`,
    name: row[1],
    location: row[2],
    ward: { code: w, name: ward.n },
    state: getState(stateSlug)!,
    lga: getLga(stateSlug, lgaSlug)!,
  };
}

/** Senate, House of Reps and State Assembly seats that cover an LGA, by name. */
export async function constituenciesFor(stateSlug: string, lgaSlug: string) {
  const lga = getLga(stateSlug, lgaSlug);
  const data = await getStateData(stateSlug);
  if (!lga || !data) return null;
  const names = (ids: string[]) =>
    ids.map((id) => data.races.find((r) => r.id === id)?.name).filter((n): n is string => Boolean(n));
  return { senate: names(lga.senate), reps: names(lga.reps), assembly: names(lga.assembly) };
}

/** Every LGA as [state, lga], for prerendering the area pages and the sitemap. */
export function allLgaPaths() {
  return Object.values(LGA_BY_CODE).map((p) => p.split("/") as [string, string]);
}
